    const mesh = new Mesh(geometry, material);
    mesh.frustumCulled = false;
    scene.add(mesh);

    // Audio state.
    let bass = 0;
    let mids = 0;
    let highs = 0;
    let peakB = 0.02;
    let peakM = 0.02;
    let peakH = 0.02;
    let slowBass = 0;
    let slowFlux = 0;
    let slowSnare = 0;
    let peakFlux = 0.001;
    const prevMags = new Float32Array(128);
