        const decay = Math.exp(-dt / 4);
        peakB = Math.max(rawB, peakB * decay, 0.02);
        peakM = Math.max(rawM, peakM * decay, 0.02);
        peakH = Math.max(rawH, peakH * decay, 0.02);
        const nB = Math.min(1, rawB / peakB);
