        const respawn = (i: number) => {
          const ux = -Math.sin(head[i]);
          const uy = Math.cos(head[i]);
          const ax = Math.abs(ux);
          const ay = Math.abs(uy);
          if (rand() * (ax + ay) < ax) {
            px[i] = -Math.sign(ux) * (xB - 0.05);
            py[i] = (rand() * 2 - 1) * 1.1;
          } else {
            py[i] = -Math.sign(uy) * (yB - 0.05);
            px[i] = (rand() * 2 - 1) * hw;
