            carryT[i] = -100;
            strokeDur[i] = 1;
            strokeNextAt[i] = -100;
            strokeStart[i] = -100;
            strokesLeft[i] = 0;
            tdX[i] = Math.sin(head[i]);
            tdY[i] = -Math.cos(head[i]);
            tdPhi[i] = Math.atan2(tdY[i], tdX[i]);
            tdOm[i] = 0;
