        const heroCy = 0.3;
        const heroHx = aspect * 0.2;
        const heroHy = 0.3;
        const roam = Math.max(0, Math.min(1, c.heroRoam ?? 0.8));
        if (heroNext < 0 || t >= heroNext) {
