    let rr = mix(0.05, 0.08, lf) * (0.6 + 0.6 * kelpHash(hc * 13.1 + 3.0));
    let tw = 0.55 + 0.45 * sin(t * (0.8 + 2.0 * hc) + hc * 50.0);
