        let fil = kelpPNoise(vec2f(ang * 0.15915494 * 48.0, rn * 3.0 - t * 0.08 * sunSwirl), 48.0);
        let fil2 = kelpPNoise(vec2f(ang * 0.15915494 * 96.0, rn * 5.0 + 3.0), 96.0);
        let filament = smoothstep(0.3, 0.8, fil * 0.65 + fil2 * 0.35);
