      // Subtle limb darkening toward the edge, with a narrow hot orange band right at the rim.
      surf = surf * (0.55 + 0.45 * smoothstep(0.0, 0.22, z)) + vec3f(0.9, 0.42, 0.08) * exp(-z / 0.01) * 0.25;
