      async evaluate(inputs, evaluation) {
        baseTex.value = inputs.image.texture as Texture;
        return { image: await evaluation.render(scene, camera) };
      },
      reset() {
        level = 0;
        gain = 0.05;
      },
      dispose() {
        geometry.dispose();
        material.dispose();
      },
    };
  },
